pub fn clip(a: &[String]) -> Vec<String> {
    a.iter()
        .filter(|s| !runtime_frame(s))
        .map(|s| fold_hex(s))
        .collect()
}

fn runtime_frame(s: &str) -> bool {
    s.starts_with("__asan") || s.starts_with("__interceptor") || s.starts_with("__hwasan")
}

fn fold_hex(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    while i < b.len() {
        if i + 2 < b.len() && b[i] == b'0' && (b[i + 1] == b'x' || b[i + 1] == b'X') && b[i + 2].is_ascii_hexdigit() {
            out.push_str("0xHEX");
            i += 2;
            while i < b.len() && b[i].is_ascii_hexdigit() { i += 1; }
        } else {
            out.push(b[i] as char);
            i += 1;
        }
    }
    out
}

pub fn take(text: &str) -> Result<(String, Vec<String>), i32> {
    if text.trim().is_empty() { return Err(3); }
    let mut kind: Option<String> = None;
    let mut frames = Vec::new();
    let mut summary = false;
    for line in text.lines() {
        if line.contains("ERROR:") {
            if kind.is_some() { return Err(3); }
            let rest = line.split_once("ERROR:").map(|x| x.1).unwrap_or("").trim();
            let after = rest.strip_prefix("AddressSanitizer:").ok_or(3)?.trim();
            let k = after.split(" on ").next().unwrap_or("").trim();
            if k.is_empty() { return Err(3); }
            kind = Some(k.to_string());
        }
        let trimmed = line.trim_start();
        if trimmed.starts_with('#') {
            let hash_end = trimmed.find(char::is_whitespace).ok_or(3)?;
            if !trimmed[1..hash_end].chars().all(|c| c.is_ascii_digit()) { return Err(3); }
            let after = trimmed[hash_end..].split_once(" in ").map(|x| x.1).ok_or(3)?;
            let sym = after.split_whitespace().next().unwrap_or("");
            if sym.is_empty() { return Err(3); }
            frames.push(sym.to_string());
        }
        if trimmed.starts_with("SUMMARY: AddressSanitizer") { summary = true; }
    }
    let kind = kind.ok_or(3)?;
    if frames.is_empty() || !summary { return Err(3); }
    let frames = clip(&frames);
    if frames.is_empty() { return Err(3); }
    Ok((kind, frames))
}
