#[path = "../treyfun/clip.rs"]
mod clip;

use std::collections::BTreeMap;

#[derive(Clone)]
pub struct Rec {
    pub issue: i32,
    pub kind: String,
    pub frames: Vec<String>,
    pub body: String,
}

pub fn tally(a: &str) -> Result<Vec<Rec>, i32> {
    let paths = crate::walk::gather(a)?;
    let mut bag: BTreeMap<String, Rec> = BTreeMap::new();
    for path in paths {
        let text = std::fs::read_to_string(&path).map_err(|_| 3)?;
        let (kind, frames) = clip::take(&text)?;
        let body = frames.join(" | ");
        let identity = frames.join("\u{1f}");
        let rec = Rec { issue: 0, kind, frames, body };
        match bag.get(&identity) {
            Some(old) if old.kind != rec.kind => return Err(3),
            Some(_) => {}
            None => { bag.insert(identity, rec); }
        }
    }
    if bag.is_empty() { return Err(3); }
    let mut recs: Vec<Rec> = bag.into_values().collect();
    recs.sort_by(|a, b| a.body.cmp(&b.body).then(a.kind.cmp(&b.kind)));
    for (i, rec) in recs.iter_mut().enumerate() { rec.issue = i as i32 + 1; }
    Ok(recs)
}
