use crate::tally::Rec;

pub fn emit(rows: &[Rec]) -> i32 {
    let mut inner = String::new();
    for (i, r) in rows.iter().enumerate() {
        if i != 0 { inner.push(','); }
        inner.push_str(&format!("{{\"issue\":{},\"kind\":{},\"frames\":{},\"body\":{}}}",
            r.issue, jstr(&r.kind), jarr(&r.frames), jstr(&r.body)));
    }
    let bound = format!("{{\"findings\":[{}]}}\n", inner);
    let mut desk = String::from("issue\tkind\tbody\n");
    for r in rows {
        desk.push_str(&format!("{}\t{}\t{}\n", r.issue, r.kind, r.body));
    }
    if std::fs::create_dir_all("/app/inkbay").is_err() { return 1; }
    if std::fs::write("/app/inkbay/bound.json", bound).is_err() { return 1; }
    if std::fs::write("/app/inkbay/desk.tsv", desk).is_err() { return 1; }
    if std::fs::write("/app/inkbay/GUARD", "ok").is_err() { return 1; }
    0
}

fn jstr(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"), '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"), '\r' => out.push_str("\\r"), '\t' => out.push_str("\\t"),
            c if c < ' ' => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"'); out
}
fn jarr(v: &[String]) -> String {
    format!("[{}]", v.iter().map(|s| jstr(s)).collect::<Vec<_>>().join(","))
}
